'use client';

import * as React from 'react';
import {createComponent, type EventName} from '@lit/react';
import '@material/web/labs/gb/components/navdrawer/md-gb-nav-drawer.js';
import '@material/web/labs/gb/components/navdrawer/md-gb-nav-drawer-item.js';
import {NavDrawerElement} from '@material/web/labs/gb/components/navdrawer/nav-drawer-element.js';
import {NavDrawerItemElement} from '@material/web/labs/gb/components/navdrawer/nav-drawer-item-element.js';

/**
 * A Material Design navigation drawer custom element. Wraps <md-gb-nav-drawer>.
 * Docs: https://material-web.dev/3.0/components/navigation-drawer/
 */
export const MdNavDrawer = createComponent({
  react: React,
  tagName: 'md-gb-nav-drawer',
  elementClass: NavDrawerElement,
  events: {
    onChange: 'change' as EventName<Event>,
    onClose: 'close' as EventName<CustomEvent<{reason: string}>>,
    onClosed: 'closed' as EventName<CustomEvent<{reason: string}>>,
    onOpen: 'open' as EventName<Event>,
    onOpened: 'opened' as EventName<Event>,
  },
});

export type MdNavDrawerProps = React.ComponentProps<typeof MdNavDrawer>;

/**
 * A Material Design navigation drawer item custom element. Wraps <md-gb-nav-drawer-item>.
 * Docs: https://material-web.dev/3.0/components/navigation-drawer/
 */
export const MdNavDrawerItem = createComponent({
  react: React,
  tagName: 'md-gb-nav-drawer-item',
  elementClass: NavDrawerItemElement,
});

export type MdNavDrawerItemProps = React.ComponentProps<typeof MdNavDrawerItem>;
